export const AboutValuesSection: React.FC<AboutValuesSectionProps> = ({ data }) => {
  const valuesTitle = data?.valuesTitle || "Nuestros Valores";
  const values = data?.values && data.values.length > 0 ? data.values : DEFAULT_VALUES;

  return (
    <section className="w-full bg-[var(--light-bg-karmax)] pt-14 sm:pt-20 pb-20 sm:pb-30">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Título de la Sección */}
        <h2 className="!text-[32px] font-semibold text-[var(--dark-blue-karmax)] tracking-tight text-center mb-10 sm:mb-14">
          {valuesTitle}
        </h2>

        {/* Grid de 6 Valores */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
          {values.map((item) => (
            <div
              key={item.id}
              className="bg-white rounded-2xl p-8 sm:p-10 transition-all duration-300 flex flex-col justify-start"
            >
              {/* Contenedor del Icono */}
              <div className="w-14 h-14 flex items-center justify-center mb-4">
                {renderIcon(item.iconName)}
              </div>

              {/* Título del Valor */}
              <h3 className="font-semibold text-[var(--text-karmax)] mb-2 tracking-tight">
                {item.title}
              </h3>

              {/* Descripción */}
              <p className="text-[var(--text-karmax)] leading-relaxed">
                {item.description}
              </p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};
